#!/usr/bin/env python3
"""Generates src/cloud/mega/account/test_vectors.rs with an implementation that
is independent from the Rust code under test (Python standard library +
`cryptography`).

Algorithms (written from the public megajs 1.3.x reference, lib/crypto/aes.mjs,
lib/storage.mjs and lib/crypto/rsa.mjs; nothing is copied from it):

* v1 accounts  - "prepare_key": start from the constant 93C467E3 7DB0C7A4
  D1BE3F81 0152CB56, then 65536 rounds in which that block is AES-128-ECB
  encrypted once per 16-byte chunk of the (zero padded) UTF-8 password, using
  the chunk as the key. The login hash `uh` ("stringhash") XORs the
  lower-cased e-mail into a 16-byte accumulator word by word, encrypts it
  16384 times with the password key and keeps bytes 0..4 and 8..12.
* v2 accounts  - PBKDF2-HMAC-SHA512(password, salt, 100000 iterations,
  32 bytes): bytes 0..16 are the password key, bytes 16..32 the `uh`.
* master key   - `k` is the master key AES-128-ECB encrypted with the
  password key.
* RSA          - `privk` is AES-ECB(master key) of four MPIs (2-byte big
  endian bit length + magnitude): p, q, d, u. `csid` is an MPI holding
  m^e mod n; the session id is the first 43 bytes of m, base64url encoded.
* `tsid`       - 32 bytes `t`; valid when AES-ECB(master, t[0:16]) == t[16:32].
* node keys    - `k = "<owner or share handle>:<base64url AES-ECB(key, node
  key)>"`; share keys come from `ok` entries whose `ha` equals
  AES-ECB(master, handle || handle). Names are in `a`: AES-CBC (zero IV) of
  `MEGA{"n":...}` padded with zero bytes, keyed by the node key (files: the
  key's first half XOR second half).

Usage: python3 -I generate_account_vectors.py > ../../../src/cloud/mega/account/test_vectors.rs
The RSA key pair is generated on each run, so regenerating changes the
(committed) output; the Rust tests only depend on internal consistency.
"""
import base64
import hashlib
import json
import sys

from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode().rstrip("=")


def ecb_enc(key, data):
    e = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    return e.update(data) + e.finalize()


def cbc_enc_zero_iv(key, data):
    e = Cipher(algorithms.AES(key), modes.CBC(bytes(16))).encryptor()
    return e.update(data) + e.finalize()


def ctr(key, nonce, data):
    e = Cipher(algorithms.AES(key), modes.CTR(nonce + bytes(8))).encryptor()
    return e.update(data) + e.finalize()


def pad16(data):
    return data + bytes((-len(data)) % 16)


def pattern(length, seed=0):
    return bytes((i * 31 + 7 + seed) & 0xFF for i in range(length))


def attributes(name):
    raw = b"MEGA" + json.dumps({"n": name}, ensure_ascii=False, separators=(",", ":")).encode()
    return pad16(raw)


def fold(raw32):
    return bytes(a ^ b for a, b in zip(raw32[:16], raw32[16:]))


def v1_password_key(password: bytes) -> bytes:
    pkey = bytes.fromhex("93c467e37db0c7a4d1be3f810152cb56")
    chunks = [pad16(password[i:i + 16]) for i in range(0, len(password), 16)]
    encryptors = [Cipher(algorithms.AES(c), modes.ECB()).encryptor() for c in chunks]
    for _ in range(65536):
        for enc in encryptors:
            pkey = enc.update(pkey)
    return pkey


def v1_user_hash(email: str, key: bytes) -> str:
    data = email.encode()
    acc = [0, 0, 0, 0]
    for i in range(0, len(data), 4):
        word = int.from_bytes(data[i:i + 4].ljust(4, b"\0"), "big")
        acc[(i // 4) & 3] ^= word
    block = b"".join(w.to_bytes(4, "big") for w in acc)
    enc = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    for _ in range(16384):
        block = enc.update(block)
    return b64(block[0:4] + block[8:12])


def v2_keys(password: bytes, salt: bytes):
    derived = hashlib.pbkdf2_hmac("sha512", password, salt, 100000, 32)
    return derived[:16], b64(derived[16:])


def mpi(value: int) -> bytes:
    length = (value.bit_length() + 7) // 8
    return value.bit_length().to_bytes(2, "big") + value.to_bytes(length, "big")


def rust_bytes(data):
    return "[" + ", ".join(f"0x{b:02x}" for b in data) + "]"


def const_bytes(name, data):
    return f"pub const {name}: [u8; {len(data)}] = {rust_bytes(data)};"


def const_str(name, text):
    return f"pub const {name}: &str = {json.dumps(text, ensure_ascii=False)};"


def main():
    out = ["// @generated by tests/fixtures/mega/generate_account_vectors.py -- do not edit.",
           "// Independent (Python hashlib + `cryptography`) vectors for MEGA account login.", ""]

    master = bytes((i * 7 + 3) & 0xFF for i in range(16))
    out.append(const_bytes("MASTER_KEY", master))

    # --- key derivation ------------------------------------------------------
    # (e-mail as typed, password, lower-cased e-mail used for the hash)
    v1_cases = [
        ("Alice.Example@Example.com", "pässwörd-v1 spanning several 16 byte chunks 123"),
        ("bob@x.io", "pw"),
        ("carol@example.org", "exactly16bytes!!!"[:16]),
    ]
    out.append("pub const V1_CASES: &[(&str, &str, [u8; 16], &str, &str)] = &[")
    for email, password in v1_cases:
        key = v1_password_key(password.encode())
        uh = v1_user_hash(email.lower(), key)
        k = b64(ecb_enc(key, master))
        out.append(f"    ({json.dumps(email)}, {json.dumps(password, ensure_ascii=False)}, "
                   f"{rust_bytes(key)}, {json.dumps(uh)}, {json.dumps(k)}),")
    out.append("];")

    salt = bytes((i * 11 + 1) & 0xFF for i in range(16))
    v2_password = "correct horse battery staple ✓"
    v2_key, v2_uh = v2_keys(v2_password.encode(), salt)
    out.append(const_str("V2_PASSWORD", v2_password))
    out.append(const_str("V2_SALT_B64", b64(salt)))
    out.append(const_bytes("V2_PASSWORD_KEY", v2_key))
    out.append(const_str("V2_USER_HASH", v2_uh))
    out.append(const_str("V2_MASTER_KEY_B64", b64(ecb_enc(v2_key, master))))
    # PBKDF2 alone, so a KDF failure is told apart from a wrong key split.
    out.append(const_bytes("PBKDF2_PASSWORD_ABC_FIRST_32",
                           hashlib.pbkdf2_hmac("sha512", b"abc", b"salty", 1000, 32)))

    # --- RSA session id ------------------------------------------------------
    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    numbers = key.private_numbers()
    p, q, d = numbers.p, numbers.q, numbers.d
    n = p * q
    u = pow(q, -1, p)
    blob = pad16(mpi(p) + mpi(q) + mpi(d) + mpi(u))
    out.append(const_str("PRIVK_B64", b64(ecb_enc(master, blob))))
    m_bytes = bytes([0x40]) + pattern(255, seed=9)
    m = int.from_bytes(m_bytes, "big")
    assert m < n
    csid = pow(m, numbers.public_numbers.e, n)
    out.append(const_str("CSID_B64", b64(mpi(csid))))
    out.append(const_str("EXPECTED_SID", b64(m_bytes[:43])))
    tsid_head = pattern(16, seed=21)
    tsid = tsid_head + ecb_enc(master, tsid_head)
    out.append(const_str("TSID_B64", b64(tsid)))

    # --- node tree -----------------------------------------------------------
    user = "USERHNDL"
    share_handle = "SHAREHDL"
    share_key = bytes((i * 5 + 77) & 0xFF for i in range(16))
    ok = [{"h": share_handle,
           "k": b64(ecb_enc(master, share_key)),
           "ha": b64(ecb_enc(master, (share_handle * 2).encode()))}]
    forged = {"h": "FORGEDHD", "k": b64(ecb_enc(master, share_key)),
              "ha": b64(ecb_enc(master, bytes(16)))}

    def node(handle, parent, is_file, name, key_bytes, wrapping_key, owner, size=None, ts=1700000000):
        attr_key = fold(key_bytes) if is_file else key_bytes
        entry = {"h": handle, "p": parent, "u": user, "t": 0 if is_file else 1,
                 "a": b64(cbc_enc_zero_iv(attr_key, attributes(name))),
                 "k": f"{owner}:" + b64(ecb_enc(wrapping_key, key_bytes)), "ts": ts}
        if is_file:
            entry["s"] = size
        return entry

    def key16(seed):
        return bytes((seed * 17 + i * 7 + 3) & 0xFF for i in range(16))

    def key32(seed):
        return bytes((seed * 17 + i * 7 + 3) & 0xFF for i in range(32))

    plain_len = 3000
    download_key = key32(40)
    download_nonce = download_key[16:24]
    out.append(const_bytes("DOWNLOAD_NODE_KEY", download_key))
    out.append(f"pub const DOWNLOAD_PLAIN_LEN: usize = {plain_len};")
    out.append(const_str("DOWNLOAD_CIPHERTEXT_HEX",
                         ctr(fold(download_key), download_nonce, pattern(plain_len)).hex()))

    nodes = [
        {"h": "ROOTNODE", "p": "", "u": user, "t": 2, "ts": 1600000000},
        {"h": "INBOXNOD", "p": "", "u": user, "t": 3, "ts": 1600000000},
        {"h": "TRASHNOD", "p": "", "u": user, "t": 4, "ts": 1600000000},
        node("DIRAAAAA", "ROOTNODE", False, "Documents é", key16(1), master, user),
        node("DIRBBBBB", "DIRAAAAA", False, "Nested", key16(2), master, user),
        node("FILEAAAA", "DIRAAAAA", True, "notes 笔记.txt", key32(3), master, user, 1234, 1700000100),
        node("FILEBBBB", "ROOTNODE", True, "movie.bin", download_key, master, user, plain_len, 1700000200),
        # Only the share key opens this node (an incoming/outgoing share).
        node(share_handle, "ROOTNODE", False, "Shared folder", key16(5), master, user),
        node("FILECCCC", share_handle, True, "shared.dat", key32(6), share_key, share_handle, 77),
        # Both alternatives, the share one listed first.
        {**node("FILEDDDD", share_handle, True, "dual.dat", key32(7), master, user, 88),
         "k": f"{share_handle}:" + b64(ecb_enc(share_key, key32(7))) + f"/{user}:" + b64(ecb_enc(master, key32(7)))},
        # Not decryptable: wrapped for a foreign owner we know no key of.
        node("FILEZZZZ", "ROOTNODE", True, "foreign.bin", key32(8), bytes(16), "OTHERUSR", 5),
        node("FILEINTR", "TRASHNOD", True, "trashed.bin", key32(9), master, user, 9),
    ]
    listing = {"f": nodes, "ok": ok + [forged], "sn": "x"}
    out.append("pub const LISTING: &str = r####\"" + json.dumps(listing, ensure_ascii=False) + "\"####;")
    out.append(const_str("SHARE_HANDLE", share_handle))
    out.append(const_str("USER_HANDLE", user))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
